const tweens = [];
function addTween(durSec, update, tag) {
  if (tag) for (let i = tweens.length - 1; i >= 0; i--) if (tweens[i].tag === tag) tweens.splice(i, 1);
  tweens.push({ t0: performance.now(), dur: durSec * 1000, update, tag });
}
function stepTweens(now) {
  for (let i = tweens.length - 1; i >= 0; i--) {
    const tw = tweens[i];
    let t = (now - tw.t0) / tw.dur;
    if (t >= 1) { tweens.splice(i, 1); t = 1; }
    tw.update(t * (2 - t)); // easeOutQuad
  }
}

