// @FIGURE_CODE_BEGIN
// ── Element spec (one primitive per element) ─────────────────────────────
// wire         → CylinderGeometry(0.15,0.15,10) rotated onto X, gray #999999 (Phong)
// current arrow→ LARGE red #cc2200 ArrowHelper sitting on the wire next to the
//                hand at x≈-1.5 (below wire axis), group flips with current toggle
// I label      → addLabel '<i>I</i>' red, just under the arrow
// hand         → Group @(-3.5,0,0): palm box behind wire, 4 SLIM finger torus-arcs
//                (tube 0.085, radius 0.27) that visibly WRAP around the wire in YZ
//                planes at staggered x, fingertip caps touching the palm side,
//                knuckle bumps where fingers leave the fist, thumb capsule extended
//                ALONG +X beside the wire (pointing right, below wire axis),
//                wrist+forearm capsule exiting down-left; skin #e8c39e (Phong)
// ring sets    → 4 sets @ x=0,1.5,3,4.5 × 4 LineLoop circles in YZ planes,
//                radii .6/1.1/1.8/2.8, blue #1a6fc4; shared material per radius
// arrowheads   → 2 travelling ConeGeometry(0.07,0.22) per ring, tangent to ring
// B label      → addLabel bold 'B' + plain '→' glyph (no combining char) y≈3.3
// marker set   → Group (toggleable, hidden by default): orange sphere #ff8800 +
//                halo on set x=1.5 at radius r (55° up-front), thin radial guide
// Marker labels use style.visibility (NOT display) so _syncLabels never un-hides them

/* ── Lights ─────────────────────────────────────────────────────────────── */
scene.add(new THREE.AmbientLight(0xffffff, 0.75));
const keyLight = new THREE.DirectionalLight(0xffffff, 1.05);
keyLight.position.set(2.5, 6, 5);
scene.add(keyLight);
const fillLight = new THREE.DirectionalLight(0xffffff, 0.3);
fillLight.position.set(-4, -3, -4);
scene.add(fillLight);

const tmpV = new THREE.Vector3();

/* ── Wire ───────────────────────────────────────────────────────────────── */
const wireGeo = new THREE.CylinderGeometry(0.15, 0.15, 10, 28);
wireGeo.rotateZ(Math.PI / 2);
const wire = new THREE.Mesh(wireGeo,
  new THREE.MeshPhongMaterial({ color: 0x999999, shininess: 70, specular: 0x777777 }));
scene.add(wire);
registerInteractive(wire, {
  tooltip: 'Current-carrying wire',
  title: 'Long straight wire',
  body: 'A steady current I flows along the long straight wire. Use the Current direction toggle: reversing I reverses every magnetic field arrow — the right-hand rule rigidly links the two.'
});

/* ── Red current arrow (large, on the wire beside the hand) ─────────────── */
const arrowGroup = new THREE.Group();
arrowGroup.position.set(-1.5, -0.42, 0.02);
scene.add(arrowGroup);
const curArrow = new THREE.ArrowHelper(
  new THREE.Vector3(1, 0, 0), new THREE.Vector3(-0.7, 0, 0), 1.4, 0xcc2200, 0.38, 0.22);
arrowGroup.add(curArrow);

/* ── Stylized right hand gripping the wire ──────────────────────────────── */
// Pose: fist below/behind the wire at x≈-3.5; four slim finger arcs wrap the
// wire (torus in YZ planes about the X axis); thumb capsule runs along +X
// beside the wire — matching the source engraving.
const skin = new THREE.MeshPhongMaterial({ color: 0xe8c39e, flatShading: true, shininess: 8 });
const hand = new THREE.Group();
hand.position.set(-3.5, 0, 0);
scene.add(hand);
{
  // Palm / back of fist: rounded mass BEHIND and BELOW the wire so the
  // finger arcs pass in front of it as they wrap the wire.
  const palm = new THREE.Mesh(new THREE.SphereGeometry(0.55, 18, 14), skin);
  palm.scale.set(1.25, 1.05, 0.85);
  palm.position.set(-0.30, -0.55, -0.30);
  hand.add(palm);

  // Four slim fingers wrapping the wire: torus arcs whose axis is the wire
  // (X). Each starts on the back of the fist (z<0), sweeps over the TOP of
  // the wire, down the FRONT (z>0), and ends in a fingertip cap tucked
  // toward the palm — a closed grip around the wire.
  const fingerX = [-0.66, -0.38, -0.10, 0.18];
  fingerX.forEach((fx, i) => {
    const R = 0.27 - i * 0.008;              // grip radius just outside wire
    const g = new THREE.TorusGeometry(R, 0.085, 10, 26, Math.PI * 1.45);
    g.rotateY(Math.PI / 2);                  // torus axis → X (the wire)
    g.rotateX(Math.PI * 0.55);               // arc: back → top → front → palm
    const f = new THREE.Mesh(g, skin);
    f.position.set(fx, 0, 0);
    hand.add(f);
    // Fingertip cap at the arc's end, tucked against the palm side.
    const aEnd = Math.PI * 0.55 + Math.PI * 1.45;
    const tip = new THREE.Mesh(new THREE.SphereGeometry(0.088, 8, 6), skin);
    tip.position.set(fx, R * Math.cos(aEnd), R * Math.sin(aEnd));
    hand.add(tip);
    // Knuckle where the finger leaves the fist (back of hand).
    const kn = new THREE.Mesh(new THREE.SphereGeometry(0.105, 10, 8), skin);
    kn.position.set(fx, 0.16, -0.24);
    hand.add(kn);
  });

  // Thumb: extended ALONG +X beside the wire (below its axis), pointing in
  // the current direction — the key right-hand-rule cue.
  const thumb = new THREE.Mesh(new THREE.CapsuleGeometry(0.115, 0.85, 4, 12), skin);
  thumb.rotation.z = Math.PI / 2;
  thumb.position.set(0.75, -0.30, 0.05);
  hand.add(thumb);
  const tTip = new THREE.Mesh(new THREE.SphereGeometry(0.115, 10, 8), skin);
  tTip.position.set(1.20, -0.30, 0.05);
  hand.add(tTip);
  const tBase = new THREE.Mesh(new THREE.SphereGeometry(0.17, 10, 8), skin);
  tBase.position.set(0.32, -0.32, 0.02);
  hand.add(tBase);

  // Wrist + forearm exiting down-left.
  const wrist = new THREE.Mesh(new THREE.SphereGeometry(0.34, 12, 10), skin);
  wrist.scale.set(1, 0.9, 0.85);
  wrist.position.set(-0.75, -0.95, -0.28);
  hand.add(wrist);
  const arm = new THREE.Mesh(new THREE.CapsuleGeometry(0.30, 1.2, 4, 10), skin);
  arm.position.set(-0.95, -1.55, -0.28);
  arm.rotation.z = 0.38;
  hand.add(arm);
}
registerInteractive(hand, {
  tooltip: 'Right-hand rule',
  title: 'Right-hand rule',
  body: 'Grip the wire with your RIGHT hand, thumb pointing along the current I. Your curled fingers then show the circulation direction of the magnetic field B. Reverse the current and the grip — and B — flips.'
});

/* ── Concentric field-line rings ────────────────────────────────────────── */
const ringX = [0, 1.5, 3, 4.5];
const radii = [0.6, 1.1, 1.8, 2.8];
const ringMats = radii.map(() => new THREE.LineBasicMaterial({ color: 0x1a6fc4 }));
for (const x of ringX) {
  radii.forEach((r, i) => {
    const pts = [];
    for (let k = 0; k < 96; k++) {
      const t = 2 * Math.PI * k / 96;
      pts.push(new THREE.Vector3(x, r * Math.cos(t), r * Math.sin(t)));
    }
    scene.add(new THREE.LineLoop(new THREE.BufferGeometry().setFromPoints(pts), ringMats[i]));
  });
}

/* ── Travelling arrowheads on every ring ────────────────────────────────── */
const cones = [];
const coneGeo = new THREE.ConeGeometry(0.07, 0.22, 10);
const coneMat = new THREE.MeshLambertMaterial({ color: 0x1a6fc4 });
const UP = new THREE.Vector3(0, 1, 0);
let dirSign = 1;
function placeCone(c) {
  const t = c.theta;
  c.mesh.position.set(c.x, c.r * Math.cos(t), c.r * Math.sin(t));
  tmpV.set(0, -Math.sin(t), Math.cos(t)).multiplyScalar(dirSign);
  c.mesh.quaternion.setFromUnitVectors(UP, tmpV);
}
for (const x of ringX) for (const r of radii) {
  for (const ph of [Math.PI / 2, 3 * Math.PI / 2]) {
    const mesh = new THREE.Mesh(coneGeo, coneMat);
    scene.add(mesh);
    const c = { mesh, x, r, theta: ph };
    placeCone(c);
    cones.push(c);
    registerInteractive(mesh, {
      tooltip: 'Magnetic field line',
      title: 'Field-line arrows',
      body: 'Each blue circle is a magnetic field line: B is tangent to it. Arrows circulate counterclockwise when viewed along the current (right-hand rule). Rings spread farther apart outward because B ∝ 1/r — the field weakens with distance.'
    });
  }
}

/* ── Radial marker group (toggleable; hidden by default for a clean view) ── */
const MARK_X = 1.5, MARK_TH = 0.96;
const markerGroup = new THREE.Group();
scene.add(markerGroup);
const guide = new THREE.Line(
  new THREE.BufferGeometry().setFromPoints(
    [new THREE.Vector3(MARK_X, 0, 0), new THREE.Vector3(MARK_X, 0.34, 0.49)]),
  new THREE.LineBasicMaterial({ color: 0xcc7722 }));
markerGroup.add(guide);
const marker = new THREE.Mesh(new THREE.SphereGeometry(0.1, 16, 12),
  new THREE.MeshBasicMaterial({ color: 0xff8800 }));
markerGroup.add(marker);
const halo = new THREE.Mesh(new THREE.SphereGeometry(0.19, 16, 12),
  new THREE.MeshBasicMaterial({ color: 0xffb84d, transparent: true, opacity: 0.35, depthWrite: false }));
markerGroup.add(halo);
marker.position.set(MARK_X, 0.8 * Math.cos(MARK_TH), 0.8 * Math.sin(MARK_TH));
halo.position.copy(marker.position);
registerInteractive(marker, {
  tooltip: 'Field strength marker',
  title: 'B at distance r',
  body: 'The orange marker sits at distance r from the wire. For a long straight wire B = μ₀I/(2πr): double r and B halves. The readout is normalized so B = 1.00 at r = 0.6.'
});

/* ── Camera ─────────────────────────────────────────────────────────────── */
setCameraView({ projection: 'perspective', azimuthDeg: 75, elevationDeg: 10, rollDeg: 0, heightFraction: 0.6 });

controls.minAzimuthAngle = -0.7;
controls.maxAzimuthAngle = 1.3;
controls.minPolarAngle = 0.7;
controls.maxPolarAngle = 1.75;
controls.enablePan = false;
controls.minDistance = 7;
controls.maxDistance = 45;
document.getElementById('btnReset').style.display = '';

/* ── Labels ─────────────────────────────────────────────────────────────── */
// Plain 'B' + separate arrow glyph: the combining vector arrow (U+20D7) is
// missing from many fonts and rendered as a tofu box in the previous attempt.
addLabel('<b>B</b>&#8594;', new THREE.Vector3(4.5, 3.35, 0), { fontSize: '26px' });
addLabel('<i>I</i>', new THREE.Vector3(-1.5, -0.95, 0), { color: '#cc2200', fontSize: '18px' });
const rLab = addLabel('<i>r</i>', new THREE.Vector3(MARK_X, 0.23, 0.33),
  { color: '#8a5a1a', fontSize: '14px', offset: [-14, 2] });
const markerLab = addLabel('', marker.position.clone(),
  { color: '#9a4a00', fontSize: '17px', background: 'rgba(255,255,255,0.88)', offset: [-40, -190] });

/* ── Marker visibility toggle ───────────────────────────────────────────── */
// _syncLabels rewrites style.display every frame for in-frustum labels, so the
// marker labels must be hidden via style.visibility (never touched by sync) —
// display:none alone was silently un-hidden, leaking the readout in the clean view.
function setMarkerVisible(on) {
  markerGroup.visible = on;
  rLab.div.style.visibility = on ? 'visible' : 'hidden';
  markerLab.div.style.visibility = on ? 'visible' : 'hidden';
  document.getElementById('chkMarker').checked = on;
  if (!on) ringMats.forEach(m => m.color.setHex(0x1a6fc4));
}

/* ── Tween engine ───────────────────────────────────────────────────────── */
const tweens = [];
function addTween(durSec, update, tag) {
  if (tag) for (let i = tweens.length - 1; i >= 0; i--) if (tweens[i].tag === tag) tweens.splice(i, 1);
  tweens.push({ t0: performance.now(), dur: durSec * 1000, update, tag });
}
function stepTweens(now) {
  for (let i = tweens.length - 1; i >= 0; i--) {
    const tw = tweens[i];
    let t = (now - tw.t0) / tw.dur;
    if (t >= 1) { tweens.splice(i, 1); t = 1; }
    tw.update(t * (2 - t));
  }
}

/* ── State appliers ─────────────────────────────────────────────────────── */
function setDirection(dir, animateFlip = true) {
  dirSign = dir === 'Leftward' ? -1 : 1;
  document.getElementById('btnCurR').classList.toggle('active', dirSign === 1);
  document.getElementById('btnCurL').classList.toggle('active', dirSign === -1);
  const target = dirSign === 1 ? 0 : Math.PI;
  if (animateFlip) {
    const h0 = hand.rotation.y, a0 = arrowGroup.rotation.y;
    addTween(0.9, e => { hand.rotation.y = h0 + (target - h0) * e; }, 'hand');
    addTween(0.9, e => { arrowGroup.rotation.y = a0 + (target - a0) * e; }, 'arrow');
  } else {
    hand.rotation.y = target;
    arrowGroup.rotation.y = target;
  }
}

let curR = 0.8;
function setRadius(r, fromSlider = false) {
  r = Math.min(3, Math.max(0.6, r));
  curR = r;
  const y = r * Math.cos(MARK_TH), z = r * Math.sin(MARK_TH);
  marker.position.set(MARK_X, y, z);
  halo.position.set(MARK_X, y, z);
  const p = guide.geometry.attributes.position;
  p.setXYZ(1, MARK_X, y, z);
  p.needsUpdate = true;
  guide.geometry.computeBoundingSphere();
  rLab.pos.set(MARK_X, y * 0.5, z * 0.5);
  markerLab.pos.set(MARK_X, y, z);
  markerLab.div.innerHTML =
    `r = ${r.toFixed(2)}<br>B = μ<sub>0</sub>I/(2πr) = <b>${(0.6 / r).toFixed(2)}</b>`;
  if (markerGroup.visible) {
    let best = 0;
    for (let i = 1; i < radii.length; i++)
      if (Math.abs(radii[i] - r) < Math.abs(radii[best] - r)) best = i;
    ringMats.forEach((m, i) => m.color.setHex(i === best ? 0x35b6ff : 0x1a6fc4));
  }
  if (!fromSlider) {
    document.getElementById('rSlider').value = r;
    document.getElementById('rVal').textContent = r.toFixed(2);
  }
}

/* ── Discrete controls wiring ───────────────────────────────────────────── */
document.getElementById('btnCurR').onclick = () => setDirection('Rightward', true);
document.getElementById('btnCurL').onclick = () => setDirection('Leftward', true);
document.getElementById('chkMarker').addEventListener('change', (e) => {
  setMarkerVisible(e.target.checked);
  if (e.target.checked) setRadius(curR); // refresh highlight + readout
});
const rSlider = document.getElementById('rSlider');
rSlider.addEventListener('input', () => {
  const r = parseFloat(rSlider.value);
  document.getElementById('rVal').textContent = r.toFixed(2);
  if (!markerGroup.visible) setMarkerVisible(true); // sliding reveals the marker
  setRadius(r, true);
});

/* ── Spin view ──────────────────────────────────────────────────────────── */
let spinOn = false, spinT = 0, spinAz0 = 0, spinPol0 = 1.4;
const btnSpin = document.getElementById('btnSpin');
function setSpin(on) {
  spinOn = on;
  btnSpin.classList.toggle('active', spinOn);
  btnSpin.textContent = spinOn ? '⏸ Stop spin' : '▶ Spin view (reveal true circles)';
  if (spinOn) {
    const off = camera.position.clone().sub(controls.target);
    spinAz0 = Math.atan2(off.x, off.z);
    spinPol0 = Math.acos(Math.min(1, Math.max(-1, off.y / off.length())));
    spinT = 0;
  }
}
btnSpin.onclick = () => setSpin(!spinOn);
controls.addEventListener('start', () => { if (spinOn) setSpin(false); });

/* ── Demo steps ─────────────────────────────────────────────────────────── */
const steps = [
  {
    title: 'Thumb along the current',
    narration: 'Current flows rightward, the thumb points right, and the blue arrows circulate to match the curl of the fingers (counterclockwise when viewed along the current).',
    state: { currentDirection: 'Rightward', radialDistance: 0.8 }
  },
  {
    title: 'Field weakens with distance',
    narration: 'Drag the marker out to r = 2.5: it lands on a widely separated outer ring and the B readout drops to roughly one third — B ∝ 1/r.',
    state: { currentDirection: 'Rightward', radialDistance: 2.5 }
  },
  {
    title: 'Reverse the current',
    narration: 'Switch the current leftward: the red arrow and thumb flip, and every blue arrowhead reverses. The right-hand rule still holds.',
    state: { currentDirection: 'Leftward', radialDistance: 1.5 }
  }
];
let stepIdx = -1;
function goToStep(i) {
  stepIdx = Math.max(0, Math.min(steps.length - 1, i));
  const s = steps[stepIdx];
  document.getElementById('stepTitle').textContent = `Step ${stepIdx + 1}: ${s.title}`;
  document.getElementById('stepNarr').textContent = s.narration;
  document.getElementById('stepCount').textContent = `${stepIdx + 1} / ${steps.length}`;
  const wantLeft = s.state.currentDirection === 'Leftward';
  if (wantLeft !== (dirSign === -1)) setDirection(s.state.currentDirection, true);
  setMarkerVisible(true); // steps narrate the marker, so reveal it
  const r0 = curR, r1 = s.state.radialDistance;
  addTween(1.4, e => setRadius(r0 + (r1 - r0) * e), 'radius');
}
document.getElementById('btnPrev').onclick = () => goToStep(stepIdx - 1);
document.getElementById('btnNext').onclick = () => goToStep(stepIdx + 1);

/* ── Initial state: clean view matching the source (marker hidden) ──────── */
setDirection('Rightward', false);
setRadius(0.8);
setMarkerVisible(false);

/* ── Animation loop ─────────────────────────────────────────────────────── */
let lastTick = performance.now();
function tick() {
  requestAnimationFrame(tick);
  const now = performance.now();
  const dt = Math.min(0.05, (now - lastTick) / 1000);
  lastTick = now;
  stepTweens(now);
  for (const c of cones) {
    c.theta += (0.55 / c.r) * dirSign * dt;
    placeCone(c);
  }
  halo.scale.setScalar(1 + 0.18 * Math.sin(now * 0.006));
  if (spinOn) {
    spinT += dt;
    const R = camera.position.distanceTo(controls.target);
    const az = spinAz0 + 0.55 * Math.sin(spinT * 0.45);
    camera.position.set(
      controls.target.x + R * Math.sin(spinPol0) * Math.sin(az),
      controls.target.y + R * Math.cos(spinPol0),
      controls.target.z + R * Math.sin(spinPol0) * Math.cos(az));
  }
}
tick();
// @FIGURE_CODE_END

Output ONLY the JSON evaluation object.

systemPrompt:
You are the orchestration agent for an iterative figure-generation loop. Generation works by taking an original 2D figure, making a generation plan, generating an interactive 3D figure, and evaluating it.

You will receive the critic evaluation, including failure modes, scores, notes, and action items.
Your job is to decide which part of the system is most responsible for the problem:
- planner: the interaction plan or conceptual decomposition is wrong, incomplete, or missing the right elements
- generator: the plan is close to right, but the rendered implementation, labels, layout, interactivity, or execution is broken
- none: the figure is good enough to stop iterating

Use the failure modes and action items as the primary evidence. Do not decide from raw score thresholds alone.
Prefer planner when the critic indicates concept misunderstanding, missing core elements, wrong primitives, or the wrong overall interaction structure.
Prefer generator when the concept is right but the execution needs concrete implementation fixes like labels, wiring, geometry details, styling, or broken controls.

Return ONLY valid JSON with this exact shape:
{
	"next_step": "pass | fix_plan | refine_generation",
	"rationale": "one concise sentence explaining the decision"
}

